export function loadBBRData() {
  const cleanSigla = (s) => (s ? String(s).replace(/^#\s*/, '').trim() : '');

  const sanitizeData = (data) => {
    if (Array.isArray(data?.centrais)) {
      data.centrais = data.centrais.map(c => ({
        ...c,
        sigla: cleanSigla(c.sigla),
        nome: c.nome ? c.nome.replace(/^Central\s+#\s*/, 'Central ').replace(/^#\s*/, '') : c.sigla ? `Central ${cleanSigla(c.sigla)}` : c.nome
      }));
    }
    return data;
  };

  try {
    // Clear legacy keys from older versions
    ['backbone_bbr_data_v1', 'backbone_bbr_data_v2', 'backbone_bbr_data_v3', 'backbone_bbr_data_v4', 'backbone_bbr_data_v5', 'backbone_bbr_data_v6_sheets_full', 'backbone_bbr_data_v7_sheets', 'backbone_bbr_data_v8_sheets_fixed'].forEach(k => {
      try { localStorage.removeItem(k); } catch(e) {}
    });

    const saved = localStorage.getItem(STORE_KEY);
    if (saved) {
      const parsed = JSON.parse(saved);
      if (parsed && Array.isArray(parsed.centrais) && parsed.centrais.length >= 100 && Array.isArray(parsed.cabos) && parsed.cabos.length >= 50) {
        return sanitizeData({ ...DADOS_INICIAIS_BBR, ...parsed });
      }
    }
    return sanitizeData({ ...DADOS_INICIAIS_BBR });
  } catch (e) {
    console.error('Erro ao ler localStorage do BBR:', e);
  }

  return sanitizeData({ ...DADOS_INICIAIS_BBR });
}

export function saveBBRData(data) {
  try {
    localStorage.setItem(STORE_KEY, JSON.stringify(data));
  } catch (e) {
    console.warn('Aviso: localStorage quota excedida ou indisponível. Dados mantidos na memória.', e);
  }
}

export function resetBBRData() {
  try {
    localStorage.removeItem(STORE_KEY);
  } catch (e) {
    console.error('Erro ao resetar localStorage do BBR:', e);
  }
  return DADOS_INICIAIS_BBR;
}

export const getBBRStore = loadBBRData;
export const setBBRStore = saveBBRData;
